using System;using System.Collections.Generic;using System.Linq;using System.Reflection;using System.Text.Json;using Deception.PolyModAdapter;
namespace HarmonyLib{public sealed class HarmonyMethod{public HarmonyMethod(MethodInfo m){}}public sealed class Harmony{public void Patch(MethodInfo m,HarmonyMethod? a,HarmonyMethod? b,object? c,HarmonyMethod? d,object? e=null){}}}
namespace Il2CppSystem{public class Object{static long Next;public IntPtr Pointer{get;}=new(++Next);}}
namespace Il2CppSystem.Collections.Generic{
 public sealed class List<T>:Il2CppSystem.Object{readonly System.Collections.Generic.List<T> Items=new();public int Count=>Items.Count;public T this[int i]=>Items[i];public void Add(T value)=>Items.Add(value);}
 public sealed class Dictionary<K,V>:Il2CppSystem.Object where K:notnull{readonly System.Collections.Generic.Dictionary<K,V> Items=new();public int Count=>Items.Count;public V this[K k]{get=>Items[k];set=>Items[k]=value;}public bool ContainsKey(K k)=>Items.ContainsKey(k);public bool Remove(K k)=>Items.Remove(k);}
}
public enum DiplomacyRelationState{Neutral=0,Peace=1,War=2,CoolDown=3}
public sealed class DiplomacyRelation:Il2CppSystem.Object{public DiplomacyRelationState State{get;set;}public int LastAttackTurn{get;set;}=-10;public int PreviousAttackTurn{get;set;}=-10;public int EmbassyLevel{get;set;}=2;}
public sealed class PlayerState:Il2CppSystem.Object{public byte Id{get;set;}public Il2CppSystem.Collections.Generic.Dictionary<byte,DiplomacyRelation> relations{get;set;}=new();}
public class ActionBase:Il2CppSystem.Object{public byte PlayerId{get;set;}}
public sealed class DestroyEmbassyAction:ActionBase{public byte OpponentId{get;set;}public DestroyEmbassyAction(byte a,byte b){PlayerId=a;OpponentId=b;}}
public sealed class GameState:Il2CppSystem.Object{public object Map{get;set;}=new Il2CppSystem.Object();public byte CurrentPlayer{get;set;}=1;public uint CurrentTurn{get;set;}=20;public Dictionary<byte,PlayerState> Players=new();Il2CppSystem.Collections.Generic.List<ActionBase> Stack=new();public bool ThrowSet;public Il2CppSystem.Collections.Generic.List<ActionBase> ActionStack{get=>Stack;set{Stack=value;if(ThrowSet){ThrowSet=false;throw new Exception("queue setter");}}}public bool TryGetPlayer(byte id,out PlayerState? p)=>Players.TryGetValue(id,out p);}
public static class PlayerDiplomacyExtensions{
 public static int Fail,Calls;static void Point(int i){if(Fail==i){Fail=0;throw new Exception("hostile phase"+i);}}
 public static void ModifyDiplomacyRelationsFromAttack(PlayerState a,byte b,GameState s){Calls++;Point(1);var ar=Get(a,b);ar.PreviousAttackTurn=ar.LastAttackTurn;ar.LastAttackTurn=(int)s.CurrentTurn;Point(2);var br=Get(s.Players[b],a.Id);br.PreviousAttackTurn=(int)s.CurrentTurn;Point(3);s.ActionStack.Add(new DestroyEmbassyAction(a.Id,b));Point(4);s.ActionStack.Add(new DestroyEmbassyAction(b,a.Id));Point(5);}
 static DiplomacyRelation Get(PlayerState p,byte id){if(!p.relations.ContainsKey(id))p.relations[id]=new();return p.relations[id];}}
namespace Deception.PolyModAdapter{internal static class NativeRegroupSession{internal static bool Active=true;internal static bool Ready(object state)=>Active;}}
namespace Deception.Tests{public static class HostilityTests{
 static int Assertions;static List<string> Cases=new();static void Check(bool b,string why){Assertions++;if(!b)throw new Exception(why);}static bool Throws(Action a){try{a();return false;}catch{return true;}}
 static void Test(string name,Action body){try{NativeRegroupSession.Active=true;PlayerDiplomacyExtensions.Fail=PlayerDiplomacyExtensions.Calls=0;body();Cases.Add(name);}catch(Exception e){throw new Exception(name,e);}}
 static GameState Make(bool existing=true){var s=new GameState();s.Players[1]=new(){Id=1};s.Players[2]=new(){Id=2};s.Players[3]=new(){Id=3};if(existing){s.Players[1].relations[2]=new(){LastAttackTurn=3,PreviousAttackTurn=2};s.Players[2].relations[1]=new(){LastAttackTurn=7,PreviousAttackTurn=6};}s.Players[1].relations[3]=new(){LastAttackTurn=8};s.ActionStack.Add(new ActionBase{PlayerId=1});return s;}
 static void Restored(GameState s,object queue,bool existing){Check(Native.Same(queue,s.ActionStack)&&s.ActionStack.Count==1,"exact original queue restored");Check(s.Players[1].relations.ContainsKey(2)==existing&&s.Players[2].relations.ContainsKey(1)==existing,"dictionary membership restored");if(existing)Check(s.Players[1].relations[2].LastAttackTurn==3&&s.Players[1].relations[2].PreviousAttackTurn==2&&s.Players[2].relations[1].LastAttackTurn==7&&s.Players[2].relations[1].PreviousAttackTurn==6,"pair timestamps restored");Check(s.Players[1].relations[3].LastAttackTurn==8,"unrelated relation preserved");}
 public static int Run(){try{
 Test("HOSTILE-001-prepare-readonly",()=>{var s=Make();var q=s.ActionStack;var p=NativeBlackmailHostility.Prepare(s,1,2);Restored(s,q,true);Check(PlayerDiplomacyExtensions.Calls==0,"planning did not execute hostility");p.Rollback();Restored(s,q,true);});
 Test("HOSTILE-002-native-pair-queued-without-embassy-execution",()=>{var s=Make();var q=s.ActionStack;var p=NativeBlackmailHostility.Prepare(s,1,2);p.Attach();Check(s.ActionStack.Count==3&&!Native.Same(s.ActionStack,q),"two native actions staged");Check(s.Players[1].relations[2].LastAttackTurn==20&&s.Players[1].relations[2].PreviousAttackTurn==3&&s.Players[2].relations[1].PreviousAttackTurn==20,"native timestamps match attack");Check(s.Players[1].relations[2].EmbassyLevel==2&&s.Players[2].relations[1].EmbassyLevel==2,"no direct embassy destruction");Check(((DestroyEmbassyAction)s.ActionStack[1]).OpponentId==2&&((DestroyEmbassyAction)s.ActionStack[2]).OpponentId==1,"only pair actions");p.Accept();Check(Throws(p.Rollback),"committed stage cannot undo");});
 foreach(bool existing in new[]{true,false})for(int phase=1;phase<=5;phase++){int f=phase;Test("HOSTILE-003-partial-rollback-"+existing+"-"+phase,()=>{var s=Make(existing);var q=s.ActionStack;var p=NativeBlackmailHostility.Prepare(s,1,2);PlayerDiplomacyExtensions.Fail=f;Check(Throws(p.Attach),"injected native exception");p.Rollback();Restored(s,q,existing);});}
 Test("HOSTILE-004-queue-setter-mutates-then-throws",()=>{var s=Make(false);var q=s.ActionStack;var p=NativeBlackmailHostility.Prepare(s,1,2);s.ThrowSet=true;Check(Throws(p.Attach),"setter throw");p.Rollback();Restored(s,q,false);});
 Test("HOSTILE-005-missing-relations-created-and-accepted",()=>{var s=Make(false);var p=NativeBlackmailHostility.Prepare(s,1,2);Check(!s.Players[1].relations.ContainsKey(2),"prepare has no GetRelation mutation");p.Attach();p.Accept();Check(s.Players[1].relations.ContainsKey(2)&&s.Players[2].relations.ContainsKey(1),"native created relation persists");});
 foreach(string guard in new[]{"turn","actor","map","queue","relation","dictionary","player","session","peace"})Test("HOSTILE-006-stale-"+guard,()=>{var s=Make();var p=NativeBlackmailHostility.Prepare(s,1,2);switch(guard){case"turn":s.CurrentTurn++;break;case"actor":s.CurrentPlayer=2;break;case"map":s.Map=new Il2CppSystem.Object();break;case"queue":s.ActionStack=new();break;case"relation":s.Players[1].relations[2].LastAttackTurn++;break;case"dictionary":s.Players[1].relations=new();break;case"player":s.Players[1]=new(){Id=1};break;case"session":NativeRegroupSession.Active=false;break;case"peace":s.Players[2].relations[1].State=DiplomacyRelationState.Peace;break;}Check(Throws(p.Attach)&&PlayerDiplomacyExtensions.Calls==0,"stale stage cannot invoke native hostility");});
 Test("HOSTILE-007-peace-read-no-insert-and-bidirectional",()=>{var s=Make(false);Check(!NativeBlackmailHostility.IsPeace(s,1,2)&&!s.Players[1].relations.ContainsKey(2)&&!s.Players[2].relations.ContainsKey(1),"read guard did not create relations");s.Players[2].relations[1]=new(){State=DiplomacyRelationState.Peace};Check(NativeBlackmailHostility.IsPeace(s,1,2)&&Throws(()=>NativeBlackmailHostility.Prepare(s,1,2)),"reciprocal peace blocks hostility");});
 Test("HOSTILE-008-double-attach-and-unattached-accept-denied",()=>{var s=Make();var p=NativeBlackmailHostility.Prepare(s,1,2);Check(Throws(p.Accept),"unattached cannot accept");p.Attach();Check(Throws(p.Attach)&&PlayerDiplomacyExtensions.Calls==1,"no duplicate hostility");p.Accept();});
 Console.WriteLine(JsonSerializer.Serialize(new{passed=true,cases=Cases.Count,assertions=Assertions,tests=Cases,scope="Production NativeApi/hostility stage against native-shaped managed ports; no gameplay"}));return 0;}catch(Exception e){Console.WriteLine(JsonSerializer.Serialize(new{passed=false,cases=Cases.Count,assertions=Assertions,error=e.ToString()}));return 1;}}
}}
